VALUES
('cbgg-wild-rovers', 'Дикие странники', 'Уменьшает перезарядку навыков «Атака горцев» и «За свободу» на 2 сек.', ARRAY['Пехота']::text[], ARRAY[]::text[], 'epic', 'https://cdn.poehali.dev/projects/455c24fb-ce5d-4076-9543-1ca6ad6daa72/bucket/treaties/1b616074f1f242d08a02e0cb6fe9845c.webp', 18, '{}'::jsonb, '{}'::jsonb, ARRAY[]::text[], true),
