('cbgg-xuanjia-cavalry-damage-doctrine', 'Доктрина урона кавалерии сюаньцзя', 'Уменьшает получаемый урон на 8%.', ARRAY['Кавалерия']::text[], ARRAY[]::text[], 'epic', 'https://cdn.poehali.dev/projects/455c24fb-ce5d-4076-9543-1ca6ad6daa72/bucket/treaties/8fe9e38b842a44a8b7d3b334923c71d7.webp', 19, '{}'::jsonb, '{}'::jsonb, ARRAY[]::text[], true),
('cbgg-xuanjia-sustainment-doctrine', 'Доктрина поддержания сюаньцзя', 'Увеличивает пробитие блока навыка «Дисциплинированный натиск» на 400 очков.', ARRAY['Кавалерия']::text[], ARRAY[]::text[], 'epic', 'https://cdn.poehali.dev/projects/455c24fb-ce5d-4076-9543-1ca6ad6daa72/bucket/treaties/8fe9e38b842a44a8b7d3b334923c71d7.webp', 19, '{}'::jsonb, '{}'::jsonb, ARRAY[]::text[], true),
('cbgg-yanyuedao-control-doctrine', 'Доктрина контроля с юэячань', 'Юнит получает иммунитет к эффектам контроля во время навыка «Высвобожденный ужас».', ARRAY['Кавалерия']::text[], ARRAY[]::text[], 'epic', 'https://cdn.poehali.dev/projects/455c24fb-ce5d-4076-9543-1ca6ad6daa72/bucket/treaties/daaf5f67984d4c82a7b9c67ea1427315.webp', 19, '{}'::jsonb, '{}'::jsonb, ARRAY[]::text[], true),
('cbgg-yanyuedao-resistance-doctrine', 'Доктрина сопротивления с юэячань', 'При использовании навыка «Нарастающий ужас» весь получаемый урон снижен на 15%.', ARRAY['Кавалерия']::text[], ARRAY[]::text[], 'epic', 'https://cdn.poehali.dev/projects/455c24fb-ce5d-4076-9543-1ca6ad6daa72/bucket/treaties/daaf5f67984d4c82a7b9c67ea1427315.webp', 19, '{}'::jsonb, '{}'::jsonb, ARRAY[]::text[], true),
('cbgg-yorkist-household-knights-oathbound', 'Рыцари дома Йорков: Клятвенно связанные', 'Навык «Кровная связь» снижает получаемый урон на 15% и восстанавливает 2.5% здоровья в секунду, пока активен.', ARRAY['Кавалерия']::text[], ARRAY[]::text[], 'epic', 'https://cdn.poehali.dev/projects/455c24fb-ce5d-4076-9543-1ca6ad6daa72/bucket/treaties/25a1b244c2e14ede9000899969099801.webp', 19, '{}'::jsonb, '{}'::jsonb, ARRAY[]::text[], true),
('cbgg-yorkist-household-knights-sunmirage', 'Рыцари дома Йорков: Солнечный мираж', 'Навык «Решимость рыцаря» увеличивает скорость передвижения на 20%, пока активен.', ARRAY['Кавалерия']::text[], ARRAY[]::text[], 'epic', 'https://cdn.poehali.dev/projects/455c24fb-ce5d-4076-9543-1ca6ad6daa72/bucket/treaties/25a1b244c2e14ede9000899969099801.webp', 19, '{}'::jsonb, '{}'::jsonb, ARRAY[]::text[], true),
('cbgg-zealot-born-anew-by-martyrdom', 'Фанатик: Рождённый заново через мученичество', 'Срабатывание навыка «Судный день» восстанавливает 50% максимального здоровья.', ARRAY['Пехота']::text[], ARRAY[]::text[], 'epic', 'https://cdn.poehali.dev/projects/455c24fb-ce5d-4076-9543-1ca6ad6daa72/bucket/treaties/f7932b947bfa4f6fa94fedd30d982c82.webp', 18, '{}'::jsonb, '{}'::jsonb, ARRAY[]::text[], true),
('cbgg-zealot-helm-of-canon', 'Фанатик: Шлем канона', 'Максимальный блок +320, навык «Миланская броня» снижает получаемый урон ещё на 5%.', ARRAY['Пехота']::text[], ARRAY[]::text[], 'epic', 'https://cdn.poehali.dev/projects/455c24fb-ce5d-4076-9543-1ca6ad6daa72/bucket/treaties/f7932b947bfa4f6fa94fedd30d982c82.webp', 18, '{}'::jsonb, '{}'::jsonb, ARRAY[]::text[], true),
